  'help.type.security': 'Keamanan',
  'help.type.other': 'Lainnya',
  'help.faq.cantLogin.q': 'Saya tidak bisa mengakses akun saya',
  'help.faq.cantLogin.a': 'Periksa apakah kamu menggunakan email dan kata sandi yang benar. Jika lupa kata sandi, klik "Lupa kata sandi?" di layar login. Jika masalah berlanjut, buat tiket dukungan.',
  'help.faq.notReceiving.q': 'Saya tidak menerima email',
  'help.faq.notReceiving.a': 'Periksa folder Spam terlebih dahulu. Pastikan penyimpananmu tidak penuh. Jika masalah berlanjut, pastikan pengirim memiliki alamat yang benar dan buat tiket.',
  'help.faq.cantSend.q': 'Saya tidak bisa mengirim email',
  'help.faq.cantSend.a': 'Periksa koneksi internetmu dan apakah alamat penerima benar. Pastikan lampiran tidak melebihi 25MB. Coba lagi dalam beberapa menit.',
  'help.faq.forgotPassword.q': 'Saya lupa kata sandi saya',
  'help.faq.forgotPassword.a': 'Di layar login, klik "Lupa kata sandi?" dan ikuti instruksi untuk mengatur ulang kata sandi melalui email pemulihan.',
  'help.faq.accountSecurity.q': 'Saya rasa akun saya telah disusupi',
  'help.faq.accountSecurity.a': 'Segera ubah kata sandimu. Periksa folder Terkirim untuk pesan yang tidak kamu kirim. Aktifkan autentikasi dua langkah di Pengaturan > Keamanan. Jika perlu, buat tiket darurat.',
  'help.faq.appAccess.q': 'Bagaimana cara mengakses aplikasi di ponsel?',
  'help.faq.appAccess.a': 'Kamu bisa mengakses Chatyy melalui browser di chatyy.com.br, atau unduh aplikasi kami di toko aplikasi perangkatmu.',
  'privacy.title': 'Kebijakan Privasi',
  'privacy.subtitle': 'Bagaimana kami melindungi dan mengelola data kamu',
  'privacy.lastUpdated': 'Terakhir diperbarui: Maret 2026',
  'privacy.dataCollection.title': 'Pengumpulan Data',
  'privacy.dataCollection.body': 'Kami hanya mengumpulkan informasi yang diperlukan untuk layanan email: nama kamu, alamat email, dan konten pesan yang dikirim dan diterima. Kami tidak menjual atau membagikan data pribadi kamu kepada pihak ketiga untuk tujuan pemasaran.',
  'privacy.dataUsage.title': 'Bagaimana Kami Menggunakan Data Kamu',
  'privacy.dataUsage.body': 'Data kamu digunakan secara eksklusif untuk mengoperasikan dan meningkatkan layanan email, termasuk pengiriman pesan, penyaringan spam, fitur AI (dengan persetujuanmu), dan keamanan akun.',
  'privacy.dataSecurity.title': 'Keamanan Data',
  'privacy.dataSecurity.body': 'Kami menggunakan enkripsi standar industri (TLS/SSL) untuk semua data dalam perjalanan dan saat diam. Sesi dilindungi dengan token terenkripsi dan perlindungan CSRF. Kami secara rutin mengaudit praktik keamanan kami.',
  'privacy.cookies.title': 'Cookies dan Penyimpanan Lokal',
  'privacy.cookies.body': 'Kami menggunakan cookies penting dan penyimpanan lokal untuk menjaga sesi kamu, mengingat preferensi (tema, bahasa), dan memberikan pengalaman yang lancar. Kami tidak menggunakan cookies pelacakan pihak ketiga.',
  'privacy.thirdParties.title': 'Layanan Pihak Ketiga',
  'privacy.thirdParties.body': 'Kami dapat menggunakan layanan pihak ketiga untuk fungsi spesifik seperti AI (Anthropic Claude) dan notifikasi push. Layanan ini mengikuti kebijakan privasi mereka sendiri dan hanya memproses data minimum yang diperlukan.',
  'privacy.rights.title': 'Hak-Hak Kamu',
  'privacy.rights.body': 'Kamu berhak mengakses, memperbaiki, mengekspor, atau menghapus data pribadi kamu kapan saja. Kamu dapat mengelola data kamu di Pengaturan atau menghubungi dukungan kami.',
  'privacy.contact.title': 'Hubungi Kami',
  'privacy.contact.body': 'Untuk pertanyaan privasi atau permintaan data, hubungi melalui privacy@chatyy.com.br. Kami akan membalas dalam waktu 30 hari.',
  'terms.title': 'Syarat Layanan',
  'terms.subtitle': 'Pedoman penggunaan Chatyy',
  'terms.lastUpdated': 'Terakhir diperbarui: Maret 2026',
  'terms.acceptance.title': 'Penerimaan Syarat',
  'terms.acceptance.body': 'Dengan mengakses atau menggunakan Chatyy, kamu setuju dengan Syarat Layanan ini. Jika kamu tidak setuju dengan bagian mana pun dari syarat ini, jangan gunakan layanan ini.',
  'terms.services.title': 'Deskripsi Layanan',
  'terms.services.body': 'Chatyy menyediakan layanan komunikasi melalui email termasuk pengiriman, penerimaan, dan pengelolaan email, serta fitur AI, integrasi kalender, dan video konferensi.',
  'terms.accounts.title': 'Akun Pengguna',
  'terms.accounts.body': 'Kamu bertanggung jawab untuk menjaga keamanan kredensialmu. Jangan bagikan kata sandimu atau izinkan akses tidak sah ke akunmu. Kamu harus berusia minimal 13 tahun untuk menggunakan layanan ini.',
  'terms.conduct.title': 'Penggunaan yang Diterima',
  'terms.conduct.body': 'Kamu setuju untuk tidak menggunakan layanan untuk mengirim spam, malware, phishing, atau konten ilegal lainnya. Jangan coba mengakses akun pengguna lain atau mengganggu infrastruktur layanan.',
  'terms.content.title': 'Kepemilikan Konten',
  'terms.content.body': 'Kamu tetap memiliki semua konten yang kamu buat dan kirim melalui layanan. Kami tidak mengklaim kepemilikan atas email atau lampiranmu. Kami dapat memproses konten sesuai kebutuhan untuk memberikan layanan.',
  'terms.limitation.title': 'Batasan Tanggung Jawab',
  'terms.limitation.body': 'Chatyy disediakan "sebagaimana adanya". Kami berusaha untuk 99,9% ketersediaan tetapi tidak menjamin layanan tanpa gangguan. Kami tidak bertanggung jawab atas kerusakan tidak langsung, insidental, atau konsekuensial yang timbul dari penggunaan layanan.',
  'terms.termination.title': 'Penutupan Akun',
  'terms.termination.body': 'Kami dapat menangguhkan atau menutup akun yang melanggar syarat ini. Kamu dapat menghapus akunmu kapan saja di Pengaturan. Setelah penutupan, data kamu akan dihapus dalam waktu 30 hari.',
  'terms.changes.title': 'Perubahan pada Syarat',
  'terms.changes.body': 'Kami dapat memperbarui syarat ini secara berkala. Kami akan memberi tahu tentang perubahan signifikan melalui email atau notifikasi di aplikasi. Penggunaan yang berkelanjutan setelah perubahan merupakan penerimaan syarat yang diperbarui.',
