  'plans.pastDue': 'Pembayaran tertunda',
  'plans.upgradeToFamily': 'Upgrade ke Pro — 1TB + 6 anggota + rekam panggilan',
  'plans.familyIncludesPlus': 'Paket Pro-mu mencakup semua dari Chatyy Plus',
  'plans.storageWarning': 'Kamu telah menggunakan {used} dari {total}',
  'plans.storageWarningUpgrade': 'Lakukan upgrade ke Chatyy One dan dapatkan 200 GB!',
  'plans.faqWhatIsPlus': 'Apa itu Chatyy One?',
  'plans.faqWhatIsPlusAnswer': 'Ini adalah paket premium dari Chatyy yang melindungi semua percakapan, foto, dan video kamu. Dengan Chatyy One, bahkan jika kamu menghapus sesuatu secara tidak sengaja, kamu bisa memulihkannya dalam waktu 30 hari. Selain itu, kamu mendapatkan 200GB penyimpanan, One AI sebagai asisten pribadi, dan bisa mengirim file hingga 100MB.',
  'plans.faqCancelAnswer': 'Paketmu tetap aktif sampai akhir periode yang dibayar. Setelah itu, kamu kembali ke paket gratis. Foto dan video yang melebihi 15GB akan disimpan selama 30 hari lagi untuk kamu unduh.',
  'plans.faqHowFamily': 'Bagaimana cara kerja paket Pro?',
  'plans.faqHowFamilyAnswer': 'Kamu bisa menambahkan hingga 4 orang dari keluargamu. Semua berbagi 500GB penyimpanan dan mendapatkan semua manfaat dari Chatyy One. Setiap orang memiliki ruang pribadi — tidak ada yang melihat file orang lain.',
  'plans.faqChangePlanAnswer': 'Ya! Jika kamu melakukan upgrade dari Plus ke Pro, hanya selisih proporsional yang akan dikenakan biaya. Jika melakukan downgrade, paket saat ini tetap berlaku sampai akhir periode.',
  'plans.faqCardDeclined': 'Kartu saya ditolak, apa yang harus saya lakukan?',
  'plans.faqCardDeclinedAnswer': 'Kamu punya 7 hari untuk memperbarui kartu. Selama periode ini, semua manfaatmu tetap berfungsi. Setelah 7 hari, paket kembali ke gratis.',
  'plans.faqDataSafe': 'Apakah data saya aman?',
  'plans.faqDataSafeAnswer': 'Ya! Data pembayaranmu diproses dengan enkripsi end-to-end. Kami tidak menyimpan nomor kartu kamu — hanya 4 digit terakhir untuk referensimu.',
